export const EMBEDDED_TESTS = {"percentage": {"subject": "quantitative-aptitude", "topic": "Percentage", "title": "CGL Tier II CT 11: Percentage - 02", "provider": "Testbook", "duration": null, "questions": [{"q": "The expenditure and income of Rajeev are in the ratio of 5:8. After some time income of Rajeev is increased by 20% but at the same time, his saving also increased by 3 1/3 %. Find increased or decreased per cent in his expenditure.", "options": [{"id": "A", "text": "20%"}, {"id": "B", "text": "33.33%"}, {"id": "C", "text": "30%"}, {"id": "D", "text": "40%"}], "answer": "C", "solution": "Shortcut Trick Let initial Income = 800, Expenditure = 500 ⇒ Savings = 300 New Income = 800 + 20% = 960 New Savings = 300 + (10/3)% = 300 + 10 = 310 New Expenditure = 960 − 310 = 650 Increase in Expenditure = [(650 − 500) ÷ 500] × 100 = 30% ∴ The correct answer is 30%. Alternate Method Given: Ratio of Expenditure to Income = 5 : 8 Increase in Incom"}, {"q": "In a medium-size township, the trend of annual immigration is an addition of 20% of the population as it was at the beginning; also 15% of the population as it was at the beginning is estimated to relocate elsewhere\" every year. If the current population is 80000, what is the likely population three years hence?", "options": [{"id": "A", "text": "90000"}, {"id": "B", "text": "91200"}, {"id": "C", "text": "92000"}, {"id": "D", "text": "92610"}], "answer": "D", "solution": "Given: The current population of medium-sized town = 80000 Calculation: Net increase in immigration = 20% Net decrease because of relocation = 15% Net increase in population in a year = 20 - 15 = 5% The total increase in population in three years = ⇒ 80000 × ({105}{100})^3 ⇒ 80000 × ({21}{20})^3 ⇒ 80000 × {9261}{8000} ⇒ 92610 ∴The answer is 92610."}, {"q": "A number is increased by 10% and then reduced by 10%. If the resultant number is 99, the original number was:", "options": [{"id": "A", "text": "98"}, {"id": "B", "text": "100"}, {"id": "C", "text": "95"}, {"id": "D", "text": "110"}], "answer": "B", "solution": "Shortcut Trick Net percentage change = x + y + (xy / 100)% Here, x = +10% and y = −10%. Net change = 10 − 10 + (10 × −10 / 100) = −1% ( decrease ). So, 99% of the original number = 99. 100% of the original number = 100. ∴ The correct answer is 100. Alternate Method Given: Percentage increase = 10% Percentage reduction = 10% Resultant number = 99 Fo"}, {"q": "The population of a city increases at a rate of 2% for the first 2 years and then, decreases at a rate of 4% for the third year. What will be the population after 3 years if the present population of the city is 62,500?", "options": [{"id": "A", "text": "62424"}, {"id": "B", "text": "62400"}, {"id": "C", "text": "63500"}, {"id": "D", "text": "65424"}], "answer": "A", "solution": "Given Current population = 62,500 Increase rate for first 2 years = 2% Decrease rate for the third year = 4% Concept: Population after 'n' years = Initial Population × (1 + rate/100) n Solution: ⇒ After 2 years, Population = 62500 × (1 + 2/100) 2 = 65025 ⇒ After 3rd year, Population = 65025 × (1 - 4/100) = 62424 Therefore, the population after 3 ye"}, {"q": "If the price of onion increases from Rs. 60/kg to Rs. 75/kg, then by what percentage a household should decrease the consumption of onion so that expenditure remains same?", "options": [{"id": "A", "text": "25 percent"}, {"id": "B", "text": "20 percent"}, {"id": "C", "text": "30 percent"}, {"id": "D", "text": "40 percent"}], "answer": "B", "solution": "Let the household consume a kg of onion earlier and b kgs later. The amount paid by the household earlier and later be Rs.60a and Rs.75b Since both prices should be the same ⇒ 60a = 75b ⇒ b = 4a/5 Required percent = (a - 4a/5)/a × 100 = 20"}, {"q": "Admissions into a commerce course of a university increase by 5% every year. If the number of admissions presently is 2400 into that course, after three years, the number of admissions is Nearest to an integer:", "options": [{"id": "A", "text": "2778"}, {"id": "B", "text": "2770"}, {"id": "C", "text": "2775"}, {"id": "D", "text": "2780"}], "answer": "A", "solution": "Given: Principal amount = 2400 Rate = 5% per annum Time = 3 years Formula used: Amount = P (1+R/100) Time Calculations: Amount = P (1+R/100) Time = 2400 (1+5/100) 3 = 2400 (21/20) 3 = 2400 × 9261/8000 = 2778.3 ≈ 2778 Hence, Number of admission after 3 year is nearest to 2778."}, {"q": "Shubham secured 345 marks out of 600 in the annual examination. Find the percentage of marks obtained by him in the examination.", "options": [{"id": "A", "text": "57.5"}, {"id": "B", "text": "57.25"}, {"id": "C", "text": "58.5"}, {"id": "D", "text": "58.25"}], "answer": "A", "solution": "The percentage of marks obtained by him in the examination = (345/600 × 100) ⇒ (345/6) ⇒ 57.5%"}, {"q": "A fruit fermenter has a certain number of pineapples of which 15% are rotten. He sells 80% of the remaining and has 510 pineapples left. How many pineapples did he have initially?", "options": [{"id": "A", "text": "3600"}, {"id": "B", "text": "3000"}, {"id": "C", "text": "5000"}, {"id": "D", "text": "7000"}], "answer": "B", "solution": "Solution: Let initial number of Pineapple be x. ⇒ 15% are rotten. Fresh Pineapple = x - 15% of x = 0.85x ⇒ 80% of the fresh Pineapple he sold, ⇒ He has 20% of the fresh Pineapple remaining i.e., 510 (given) ⇒ 20/100 × 0.85x = 510 ⇒ 1/5 × 0.85x = 510 ⇒ 0.17x = 510 ⇒ x = 510 × 100/17 = 30 × 100 = 3000 Hence, there are initially 3000 Pineapples."}, {"q": "Sushil’s income is 22% less than Abhishek’s income. Abhishek’s income is what % more than Sushil’s income?", "options": [{"id": "A", "text": "27.8%"}, {"id": "B", "text": "28.20%"}, {"id": "C", "text": "30.8%"}, {"id": "D", "text": "25.8%"}], "answer": "B", "solution": "Given: Sushil's income is 22% less than Abhishek's income. Formula Used: Percentage increase = (Difference / Original) × 100 Calculation: Let Abhishek's income be A . Sushil's income = A - 0.22A = 0.78A Difference in income = A - 0.78A = 0.22A Percentage increase = (0.22A / 0.78A) × 100 Percentage increase = (0.22 / 0.78) × 100 Percentage increase "}, {"q": "If an error of 2% is made in measures the side of a square, what will be the percentage error in area?", "options": [{"id": "A", "text": "2%"}, {"id": "B", "text": "4%"}, {"id": "C", "text": "2.2%"}, {"id": "D", "text": "4.04%"}], "answer": "D", "solution": "Concept use: Area of Square = side 2 Calculation: Let's say we have a square with a true side length of 100 units The original area of this square would be 100 units × 100 units = 10,000 square units. Now, a 2% error in measuring the side of the square. This means our measured side length would be 100 units + 2% of 100 units = 102 units. The area o"}]}, "time-work": {"subject": "quantitative-aptitude", "topic": "Time & Work", "title": "CBT Exam - pundits", "provider": "Pundits", "duration": 20, "questions": [{"q": "In an office, 75 employees can finish a project in 60 days. After few days, 15 employees left the job and the project was completed in 65 days. After how many days did the 15 employees leave? एक कार्यालय में , 75 कर्मचारी एक परियोजना को 60 दिनों में पूरा कर सकते हैं। कुछ दिनों के बाद , 15 कर्मचारियों ने नौकरी छोड़ दी और परियोजना 65 दिनों में पूरी हो गई। 15 कर्मचारियों ने कितने दिनों के बाद नौकरी छोड़ दी ?", "options": [{"id": "A", "text": "50 50"}, {"id": "B", "text": "45 45"}, {"id": "C", "text": "30 30"}, {"id": "D", "text": "40 40"}], "answer": "D", "solution": "Let the required number of days = x 75 × 60 = 75x + 60 × [65 - x] 4500 = 3900 + 75x - 60x 600 = 75x - 60x 600 = 15x; i.e. x=40 मान लीजिए आवश्यक दिनों की संख्या = x 75 × 60 = 75x + 60 × [65 - x] 4500 = 3900 + 75x - 60x 600 = 75x - 60x 600 = 15x; यानी x=40"}, {"q": "A can finish a piece of work in a certain number of days. B takes 45% more number of days, to finish the same work independently. They worked together for 58 day and then the remaining work was done by B alone in 29 days. In how many days could A have completed the work, had he worked alone? A किसी काम को कुछ दिनों में पूरा कर सकता है। B को उसी काम को स्वतंत्र रूप से पूरा करने में 45% अधिक दिन लगते हैं। उन्होंने 58 दिनों तक एक साथ काम किया और फिर शेष काम B ने अकेले 29 दिनों में पूरा किया। यदि A ने अकेले काम किया होता , तो वह काम कितने दिनों में पूरा कर सकता था ?", "options": [{"id": "A", "text": "110 days 110 दिन"}, {"id": "B", "text": "118 days 118 दिन"}, {"id": "C", "text": "98 days 98 दिन"}, {"id": "D", "text": "120 days 120 दिन"}], "answer": "B", "solution": "Ratio of time taken by A and B = 100 : 145=20:29 Then, Ratio of efficiency = 29 : 20 In 58 days work done by A & B ≔58 × 49 = 2842 Remaining work by B = 20 × 29 = 580 Total work =2842 + 580 = 3422 Time taken by A= =118 days A और B द्वारा लिए गए समय का अनुपात = 100 : 145 = 20:29 फिर , दक्षता का अनुपात = 29 : 20 58 दिनों में A और B द्वारा किया गया का"}, {"q": "A, B and C individually can complete a work in x, 30 and 45 days, respectively. B and C worked together for 6 days. The remaining work was completed by A alone in 12 days. The value of x is: A, B और C अकेले एक काम को क्रमशः x, 30 और 45 दिनों में पूरा कर सकते हैं। B और C ने मिलकर 6 दिन काम किया। शेष काम A ने अकेले 12 दिनों में पूरा किया। x का मान है:", "options": [{"id": "A", "text": "18 days 18 दिन"}, {"id": "B", "text": "20 days 20 दिन"}, {"id": "C", "text": "24 days 24 दिन"}, {"id": "D", "text": "15 days 15 दिन"}], "answer": "A", "solution": "Efficiency of A, B and C are 90/x, 3, 2 = [B + C] 6 +12[A] = 90 =5 × 6 +12[A] =30 + 12[A] = 90 A = 5 Means x = =18 days A, B और C की दक्षता 90/x, 3, 2 है = [B + C] 6 +12[A] = 90 =5 × 6 +12[A] =30 + 12[A] = 90 A = 5 मतलब x = =18 दिन"}, {"q": "P alone can complete a piece of work in 10 days while Q alone can complete the same piece of work in 15 days. To complete the work in 4 days, R is hired by P and Q. How many days does R take to complete the work alone? P अकेले एक काम को 10 दिनों में पूरा कर सकता है जबकि Q अकेले उसी काम को 15 दिनों में पूरा कर सकता है। काम को 4 दिनों में पूरा करने के लिए , P और Q ने R को काम पर रखा है। R को अकेले काम पूरा करने में कितने दिन लगते हैं ?", "options": [{"id": "A", "text": "6 days 6 दिन"}, {"id": "B", "text": "8 days 8 दिन"}, {"id": "C", "text": "9 days 9 दिन"}, {"id": "D", "text": "12 days 12 दिन"}], "answer": "D", "solution": "Let efficiency of R = R Work should be completed in 4 days = 30 ⇒ 4[5 + R] R =2.5 Then R completes the whole work = =12 days माना R की दक्षता = R कार्य 4 दिन में पूरा होना चाहिए = 30 ⇒ 4[5 + R] R =2.5 तो R पूरा कार्य पूरा कर लेता है = =12 दिन"}, {"q": "A certain number of persons can complete a piece of work in 46 days. If there were 8 persons more, the work could be finished in 16 days less. How many persons were originally there? कुछ निश्चित व्यक्ति किसी काम को 46 दिन में पूरा कर सकते हैं। यदि 8 व्यक्ति और होते , तो काम 16 दिन कम में पूरा हो सकता था। मूल रूप से कितने व्यक्ति थे ?", "options": [{"id": "A", "text": "25 25"}, {"id": "B", "text": "18 18"}, {"id": "C", "text": "15 15"}, {"id": "D", "text": "20 20"}], "answer": "C", "solution": "let no. of people =x x × 46 =[x + 8] 30 46x = 30x + 240 16x =240 x =15 माना लोगों की संख्या = x x × 46 =[x + 8] 30 46x = 30x + 240 16x =240 x =15"}, {"q": "In a press, there are three types of printing machines, P, Q and R. Machine P can print 10,000 pages in 8 hours, machine Q can finish the same task in 10 hours and machine R can finish the same task in 15 hours. All the three machines start the work at 9:00 a.m. Machine P breaks down at 11:00.a.m and machines Q and R finish the task. The approximate time of completion of the job is: एक प्रेस में तीन प्रकार की प्रिंटिंग मशीनें हैं , P, Q और R. मशीन P 8 घंटे में 10,000 पेज प्रिंट कर सकती है , मशीन Q उसी काम को 10 घंटे में पूरा कर सकती है और मशीन R उसी काम को 15 घंटे में पूरा कर सकती है . तीनों मशीनें सुबह 9:00 बजे काम शुरू करती हैं . मशीन P सुबह 11:00 बजे खराब हो जाती है और मशीन Q और R काम पूरा कर देती हैं . काम पूरा होने में लगने वाला अनुमानित समय है :", "options": [{"id": "A", "text": "2:05 p.m 2:05 p.m"}, {"id": "B", "text": "1:30 p.m 1:30 p.m"}, {"id": "C", "text": "2:30 p.m 2:30 p.m"}, {"id": "D", "text": "1:50 p.m 1:50 p.m"}], "answer": "B", "solution": "Efficiency of Machine P : Q : R = Lcm of 8, 10, 15 = 120 P= =15 Q= =12 R= =8 Efficiency of all together = 15 + 12 + 8 = 35 In 2 hours work done = 35 × 2 = 70 Work left =120 70 = 50 Completed by Q & R= =2.5 hours Total time taken =11:00 to 2.5 hours =1:30pm मशीन P : Q : R की दक्षता = 8, 10, 15 का Lcm = 120 P= =15 Q= =12 R= =8 सभी की एक साथ दक्षता = "}, {"q": "The marks scored by a student are directly proportional to the time invested in studies. If the student gets 60 marks when he studies 4 hours a day, then how many hours he should use in his studies daily to get 75 marks? एक छात्र द्वारा प्राप्त अंक सीधे तौर पर पढ़ाई में लगाए गए समय के समानुपाती होते हैं। यदि छात्र प्रतिदिन 4 घंटे पढ़ाई करके 60 अंक प्राप्त करता है , तो उसे 75 अंक प्राप्त करने के लिए प्रतिदिन अपनी पढ़ाई में कितने घंटे लगाने चाहिए ?", "options": [{"id": "A", "text": "4.5 4.5"}, {"id": "B", "text": "6 6"}, {"id": "C", "text": "5 5"}, {"id": "D", "text": "5.5 5.5"}], "answer": "C", "solution": "Marks ∝ time Marks = k × time 60 = k × 4 k = 15 ⇒ 75 =15 × time Time =5 hours अंक ∝ समय अंक = k × समय 60 = k × 4 k = 15 ⇒ 75 =15 × समय समय = 5 घंटे"}, {"q": "A certain number of person can complete a work in 34 days working 9 hours a day. If the number of persons is decreased by 40% then how many hours a day should the remaining persons work to complete the work in 51 days? कुछ व्यक्ति प्रतिदिन 9 घंटे काम करके 34 दिनों में एक काम पूरा कर सकते हैं। यदि व्यक्तियों की संख्या 40% कम हो जाती है , तो शेष व्यक्तियों को 51 दिनों में काम पूरा करने के लिए प्रतिदिन कितने घंटे काम करना चाहिए ?", "options": [{"id": "A", "text": "8 8"}, {"id": "B", "text": "10 10"}, {"id": "C", "text": "9 9"}, {"id": "D", "text": "12 12"}], "answer": "B", "solution": "Let No. of persons be 100x and No. of hours = y = 34 × 100x × 9= 60x × 51 × y y = 10 days माना व्यक्तियों की संख्या 100x है तथा घंटों की संख्या = y = 34 × 100x × 9= 60x × 51 × y y = 10 दिन"}, {"q": "A certain number of men can complete a piece of work in 6k days, where k is a natural number. By what percentage should the number of men be increased so that the work can be completed in 5k days? कुछ निश्चित संख्या में पुरुष किसी कार्य को 6k दिनों में पूरा कर सकते हैं , जहाँ k एक प्राकृतिक संख्या है। पुरुषों की संख्या में कितने प्रतिशत की वृद्धि की जानी चाहिए ताकि कार्य 5k दिनों में पूरा हो सके ?", "options": [{"id": "A", "text": "10% 10%"}, {"id": "B", "text": ""}, {"id": "C", "text": "20% 20%"}, {"id": "D", "text": "25% 25%"}], "answer": "C", "solution": "[5K × M] : [6K × M]= 5 ∶ 6 So, the number of persons increased by = ×100 = 20% [5K × M] : [6K × M]= 5 ∶ 6 इसलिए , व्यक्तियों की संख्या में वृद्धि = ×100 = 20%"}, {"q": "A work was finished by Amit, Sumit and Vinit together. Amit and Sumit together finished 70% part of the work and Sumit and Vinit together finished 50% part of the work. Who among the three is the most efficient? एक काम अमित , सुमित और विनीत ने मिलकर पूरा किया। अमित और सुमित ने मिलकर काम का 70% हिस्सा पूरा किया और सुमित और विनीत ने मिलकर काम का 50% हिस्सा पूरा किया। तीनों में से कौन सबसे कुशल है ?", "options": [{"id": "A", "text": "All are equal सभी बराबर हैं"}, {"id": "B", "text": "Vinit विनीत"}, {"id": "C", "text": "Amit अमित"}, {"id": "D", "text": "Sumit सुमित"}], "answer": "C", "solution": "Amit + Sumit =70% Vinit = 30% Sumit + Vinit = 50% So, Work done by Amit = 50%, Vinit = 30% and Sumit = 20% Therefore, most efficient is Amit अमित + सुमित = 70% विनित = 30% सुमित + विनीत = 50% अतः , अमित द्वारा किया गया कार्य = 50%, विनीत = 30% तथा सुमित = 20% अतः , सबसे कुशल अमित है"}, {"q": "A can complete a certain work in 30 days. B is 20% more efficient than A. C can complete part of the same work in 8 days. A and B together complete part of the work. The remaining work remaining work is completed by A and C together. In how many days was the entire work completed? A किसी काम को 30 दिन में पूरा कर सकता है। B, A से 20% अधिक दक्ष है। C उसी काम का भाग 8 दिन में पूरा कर सकता है। A और B मिलकर काम का भाग पूरा करते हैं। शेष काम A और C मिलकर पूरा करते हैं। पूरा काम कितने दिन में पूरा हुआ ?", "options": [{"id": "A", "text": ""}, {"id": "B", "text": "14 14"}, {"id": "C", "text": ""}, {"id": "D", "text": "13 13"}], "answer": "C", "solution": "Efficiency = A : B = 5 : 6 Time = A : B = 6 : 5 A = 30 days then B = × 5 = 25 days Total work = 30 × 5 =150 Efficiency of C = × =7.5 A+B have completed 11/15 of work, so work left =150 × = 40 Time taken by A + B together = =10 days Time taken by A + C together = = days Therefore, the entire work complete in = 10 days + days = days कार्यदक्षता = A :"}, {"q": "P can do one-fourth piece of some work in 18 days. She completed 37.5% of that work and left it. Q completed the remaining work in 40 days. Working together they will complete part of the same work in: P किसी काम का एक - चौथाई हिस्सा 18 दिनों में पूरा कर सकती है। उसने उस काम का 37.5% पूरा किया और उसे छोड़ दिया। Q ने शेष काम 40 दिनों में पूरा किया। साथ मिलकर काम करते हुए वे उसी काम का हिस्सा कितने दिनों में पूरा करेंगे :", "options": [{"id": "A", "text": "6 days 6 दिन"}, {"id": "B", "text": "10 days 10 दिन"}, {"id": "C", "text": "12 days 12 दिन"}, {"id": "D", "text": "8 days 8 दिन"}], "answer": "C", "solution": "P→ →18 = 72 days Now 37.5% work has done 62.5% left and will be completed by Q in 40 days Q can complete all work in = ×100 = 64 days Let Total work =LCM of 64 & 72 = 576 Efficiency of P = =8 and efficiency of Q = = 9 Therefore the required time = = 12 days P → → 18 = 72 दिन अब 37.5% काम हो चुका है , 62.5% काम बाकी है और Q इसे 40 दिनों में पूरा करे"}, {"q": "There are three taps of diameter 2 cm, 3 cm and 4 cm, respectively. The ratio of the water flowing through them is equal to the ratio of the square of their diameters. The biggest tap can fill an empty tank alone in 81 min. If all the taps are opened simultaneously, then how long will the tank take [in min] to be filled? तीन नल हैं जिनका व्यास क्रमशः 2 सेमी , 3 सेमी और 4 सेमी है। उनके माध्यम से बहने वाले पानी का अनुपात उनके व्यास के वर्ग के अनुपात के बराबर है। सबसे बड़ा नल अकेले एक खाली टैंक को 81 मिनट में भर सकता है। यदि सभी नल एक साथ खोल दिए जाएँ , तो टैंक को भरने में [ मिनटों में ] कितना समय लगेगा ?", "options": [{"id": "A", "text": ""}, {"id": "B", "text": ""}, {"id": "C", "text": ""}, {"id": "D", "text": ""}], "answer": "D", "solution": "According to Question: Diameter: - 2 : 3 : 4 Water Flow: - 4 : 9 : 16 Capacity = Efficiency Time =16 × 81 = 1296 Required Time = = = minutes प्रश्न के अनुसार : व्यास : - 2 : 3 : 4 जल प्रवाह : - 4 : 9 : 16 क्षमता = दक्षता × समय =16 × 81 = 1296 आवश्यक समय = = = मिनट"}, {"q": "Two pipes can fill a tank separately in 36 minutes and 45 minutes respectively. An exhaust pipe fitted in the tank can remove 40 Litres of water per minute. If all three pipes are opened together, the tank is filled in one hour. Find the capacity [in litres] of the tank. दो पाइप एक टैंक को अलग - अलग क्रमशः 36 मिनट और 45 मिनट में भर सकते हैं। टैंक में लगा एक निकास पाइप प्रति मिनट 40 लीटर पानी निकाल सकता है। यदि तीनों पाइप एक साथ खोले जाते हैं , तो टैंक एक घंटे में भर जाता है। टैंक की क्षमता [ लीटर में ] ज्ञात कीजिए।", "options": [{"id": "A", "text": "600 600"}, {"id": "B", "text": "400 400"}, {"id": "C", "text": "300 300"}, {"id": "D", "text": "1200 1200"}], "answer": "D", "solution": "If all Pipes are opened together ⇒ [5 + 4 - C] × 60 = 180 ⇒ C = 40 L/min ⇒ Capacity of tank =180 × =1200 litres यदि सभी पाइप एक साथ खोले जाएं ⇒ [5 + 4 - C] × 60 = 180 ⇒ C = 40 L/min ⇒ टैंक की क्षमता = 180 × =1200 लीटर"}, {"q": "A cistern can be filled by one of two pipes in 52 minutes and by the other pipe in 60 minutes. Both pipes are opened together for a certain time but being particularly clogged only of the full quantity of water flows through the first pipe and only of the full quantity of water flows through the second pipe. The obstructions, however, were suddenly removed in both the pipes after sometime and the cistern got filled in 15 minutes from that moment. For how many minutes did the pipes remain clogged? एक टंकी को दो पाइपों में से एक द्वारा 52 मिनट में तथा दूसरे पाइप द्वारा 60 मिनट में भरा जा सकता है। दोनों पाइपों को एक निश्चित समय के लिए एक साथ खोला जाता है , लेकिन विशेष रूप से अवरुद्ध होने के कारण पहले पाइप से केवल पानी बहता है तथा दूसरे पाइप से केवल 3/4 पानी बहता है। हालाँकि , कुछ समय बाद दोनों पाइपों में अवरोध अचानक हटा दिए गए तथा उस क्षण से 15 मिनट में टंकी भर गई। कितने मिनट तक पाइप अवरुद्ध रहे ?", "options": [{"id": "A", "text": ""}, {"id": "B", "text": ""}, {"id": "C", "text": ""}, {"id": "D", "text": ""}], "answer": "A", "solution": "According to question: × t + × 28 = 52 × 15 × t + × 28 = 52 × 15 ⇒ × t + × 28 = 52 × 15 ⇒ × t = ⇒ t = = Minutes प्रश्न के अनुसार : × t + × 28 = 52 × 15 × t + × 28 = 52 × 15 ⇒ × t + × 28 = 52 × 15 ⇒ × t = ⇒ t = = मिनट"}]}, "syllogism": {"subject": "reasoning", "topic": "Syllogism", "title": "CGL Tier II CT 16: Syllogism - 01", "provider": "Testbook", "duration": null, "questions": [{"q": "Given below are three statements followed by two conclusions । and II. You have to consider the statements to be true even if they seem to be at variance from commonly known facts. Decide which of the conclusions follow from the statements. Statements: 1. No guitar is a violin. 2. All violins are strings 3. No string is metal. Conclusion: I. No string being violin is a possibility. II. Some guitars are not strings.", "options": [{"id": "A", "text": "Both conclusion I and II follow."}, {"id": "B", "text": "Neither I nor II f ollows"}, {"id": "C", "text": "Only conclusion I follows."}, {"id": "D", "text": "Only conclusion II follows."}], "answer": "B", "solution": "The least possible Venn diagram is as follows: Conclusion: I. No string being violin is a possibility. → False ( All violins are strings, so it is not possible.) II. Some guitars are not strings. → False (There is no direct negative relation between Guitar and String, So it doesn't follow.) (Given Venn diagram follows all the statements. From the d"}, {"q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements : All flags are symbols. All symbols are prides. Some prides are bright. Conclusions : (I) All flags are prides. (II) Some flags are bright is a possibility. (III) Some symbols are bright is a possibility.", "options": [{"id": "A", "text": "Only conclusion I follows"}, {"id": "B", "text": "Only conclusion II follows"}, {"id": "C", "text": "All conclusions I, II and III follow"}, {"id": "D", "text": "Both conclusions I and II follow"}], "answer": "C", "solution": "Statements : (I) All flags are symbols, (II) All symbols are prides and (III) Some prides are bright. The Venn diagram as per the given statements: Conclusions : (I) All flags are prides. → Follow (Because all flags are symbols and all symbols are pride so that all flags are pride is definitely true) (II) Some flags are bright is a possibility. → F"}, {"q": "The statements below are followed by two conclusions labeled I and II. Assuming that the information in the statements is true, even if it appears at variance with generally established facts, decide which conclusion(s) logically and definitely follow(s) from the information given in the Statements: All knights are nuns. All nuns are men. Conclusion: I. All men are knights. II. All knights are men.", "options": [{"id": "A", "text": "Either conclusion I or conclusion II follows."}, {"id": "B", "text": "Both conclusions follow."}, {"id": "C", "text": "Only conclusion II follows."}, {"id": "D", "text": "Only conclusion I follows."}], "answer": "C", "solution": "Conclusion I: All men are knights → False (This is definitely false) Conclusion II: All knights are men → True (This is definitely true)"}, {"q": "Three Statements are given followed by two conclusions numbered I and II. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements. Statement I: No bridge is a mountain. Statement II: Some mountains are monuments. Statement III: All monuments are harbours. Conclusion I: Some harbours are mountains. Conclusion II: No bridge is a monument.", "options": [{"id": "A", "text": "Neither conclusion I nor II follows"}, {"id": "B", "text": "Only conclusion II follows"}, {"id": "C", "text": "Both conclusions I and II follow"}, {"id": "D", "text": "Only conclusion I follows"}], "answer": "D", "solution": "Conclusions: I. Some harbours are mountains → F ollow (As some mountains are monuments and all monuments are harbours. As whole monuments comes in harbours and has some part common with mountains, therefore it is true.) II. No bridge is a monument → Does not f ollow (As no bridge is a mountain and some mountains are monuments. As no direct relation"}, {"q": "Directions: In the question below are given two statements followed by two conclusions I and II. You have to take the given statements to be true even if they seem to be at variance with commonly known facts. Read all the conclusions and then decide which of the given conclusion logically follows from the given statements disregarding commonly known facts Statements: Some bed are table No table is lamp Conclusions: I. All lamp is bed II. Some bed are not lamp", "options": [{"id": "A", "text": "Only I follows"}, {"id": "B", "text": "Only II follows"}, {"id": "C", "text": "Either I or II follows"}, {"id": "D", "text": "Neither I nor II follows"}], "answer": "B", "solution": "The least possible Venn diagram is as follows Conclusions: I. All lamp is bed → False (as there is no direct relation given between lamp and bed) II. Some bed are not lamp → True (as some bed are table and no table is lamp → that portion of bed which is included in table will definitely not be lamp. the lined portion will definitely not be lamp) He"}, {"q": "In the question below, there are three statements followed by two conclusions. You have to take the given statements to be true even if they seem to be at variance with commonly known facts and then decide which of the given conclusion logically follow(s) from the given statements. Statements: 1. All keys are locks. 2. All locks are screws. 3. All doors are keys. Conclusions: I. All screws are keys. II. Some locks are keys.", "options": [{"id": "A", "text": "If only conclusion I follows"}, {"id": "B", "text": "If neither conclusion I nor II follows"}, {"id": "C", "text": "If either conclusion I or II follows"}, {"id": "D", "text": "If only conclusion II follows"}], "answer": "D", "solution": "The least possible Venn diagram for the given statements is as below: Conclusions: (1) All screws are keys → False → (All keys are screws but vise-versa is NOT true). (2) Some locks are keys → True → (As all he keys are locks thus some lock will be keys is a definite statements). Hence, Option (4) is correct. Additional Information Suppose for an E"}, {"q": "Two Statements are given followed by two conclusions numbered I and II. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements. Statements: All bottles are black. Some black are white. Conclusions: I. All blacks are bottles. II. Some blacks are not white.", "options": [{"id": "A", "text": "Both conclusions I and II follow"}, {"id": "B", "text": "Only conclusion II follows"}, {"id": "C", "text": "Neither conclusion I nor II follows"}, {"id": "D", "text": "Only conclusion I follows"}], "answer": "C", "solution": "Given Statements: All bottles are black. Some black are white. The least possible Venn diagram for the given statement is: Conclusions: I. All blacks are bottles - False (Because, some black are bottles, and all blacks are bottles can be possible only ). II. Some blacks are not white - False (Because, some black are white, but no information given "}, {"q": "Three Statements are given followed by two conclusions numbered I and II. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements. Statement I: Some books are pens. Statement II: All pens are pencils. Statement III: No pencil is a marker. Conclusion I: Some books are not pens. Conclusion II: No pen is a marker.", "options": [{"id": "A", "text": "Only conclusion I follows"}, {"id": "B", "text": "Only conclusion II follows"}, {"id": "C", "text": "Neither conclusion I nor II follows"}, {"id": "D", "text": "Both conclusions I and II follow"}], "answer": "B", "solution": "The least possible Venn diagram is: Conclusion: I: Some books are not pens. - False (Because, Some books are pens given, so some books are not pens it is not possible) II: No pen is a marker. - True (Because, All pens are pencils and No pencil is a marker so No pen is a marker it is definite)"}, {"q": "Given below both the statements are given followed by two conclusions numbered I and II. You have to consider the statements to be true even if they seem to be at variance from commonly known facts. Decide which of the conclusions follow from the statements. Statements: 1. Some peons are soldiers. 2. Some soldiers are not cooks. Conclusion: I. Some soldiers are peons. II. Some cooks are soldiers.", "options": [{"id": "A", "text": "Only conclusion I follows."}, {"id": "B", "text": "Both conclusions I and II follow."}, {"id": "C", "text": "Neither conclusion I nor II follows."}, {"id": "D", "text": "Only conclusion II follows."}], "answer": "A", "solution": "The least possible Venn diagram is given below:- Conclusion: I. Some soldiers are peons. → True ( Some peons are soldiers. So, we can say that some soldiers are peons.) II. Some cooks are soldiers. → False ( it is possible but not definite) Hence, \"option 1\" is the correct answer."}, {"q": "In this question, three statements are given, followed by two conclusions numbered I and II. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follows/follow from the statements. Statements: All notebooks are pink. All pinks are shirts. Some shirts are trousers. Conclusions: I. All trousers are notebooks. II. Some trousers are pink.", "options": [{"id": "A", "text": "Only conclusion I follows."}, {"id": "B", "text": "Both conclusions I and II follow."}, {"id": "C", "text": "Neither conclusion I nor II follows."}, {"id": "D", "text": "Only conclusion II follows."}], "answer": "C", "solution": "I. All trousers are notebooks - False (No definite relation given between trousers and notebooks , so it can be possible only). II. Some trousers are pink - False ( No definite relation given between trousers and pink , so it can be possible only )."}]}, "analogy": {"subject": "reasoning", "topic": "Analogy", "title": "CGL Tier II CT 03: Symbolic/ Number Analogy", "provider": "Testbook", "duration": null, "questions": [{"q": "Select the option that is related to the sixth number in the same way as the first number is related to the second number and the third number is related to the fourth number. 11 : 81 :: 22 : 400 :: ? : 225", "options": [{"id": "A", "text": "11"}, {"id": "B", "text": "13"}, {"id": "C", "text": "17"}, {"id": "D", "text": "15"}], "answer": "C", "solution": "The logic followed here is: Logic: (1st number - 2) 2 = 2nd number . Now, 11 : 81 → (11 - 2) 2 ⇒ 9 2 = 81. 22 : 400 → (22 - 2) 2 ⇒ 20 2 = 400. Similarly, for ? : 225 → (17 - 2) 2 ⇒ 15 2 = 225. Hence, the correct answer is \"Option 3\" ."}, {"q": "Select the set in which the numbers are related in the same way as are the numbers of the following sets. (NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13- Operations on 13 such as adding /subtracting /multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.) (7, 91, 98) (4, 52, 56)", "options": [{"id": "A", "text": "(12, 156, 168)"}, {"id": "B", "text": "(3, 36, 42)"}, {"id": "C", "text": "(8, 80, 96)"}, {"id": "D", "text": "(5, 25, 60)"}], "answer": "A", "solution": "Logic: Second Number = First Number × 13 , Third Number = First Number + Second Number Option 1) (12, 156, 168) → 156 = 12 × 13 → 168 = 12 + 156 ⇒ Satisfies the logic."}, {"q": "Select the option that is related to the third term in the same way as the second term is related to the first term and the sixth term is related to the fifth term. 42 ∶ 12 ∶∶ 77 ∶ ? ∶∶ 91 : 19", "options": [{"id": "A", "text": "15"}, {"id": "B", "text": "19"}, {"id": "C", "text": "17"}, {"id": "D", "text": "14"}], "answer": "C", "solution": "42 : 12 → (42 ÷ 7) + 6 = 6 + 6 = 12 91 : 19 → (91 ÷ 7) + 6 = 13 + 6 = 19 77 : ? → (77 ÷ 7) + 6 = 11 + 6 = 17"}, {"q": "Select the option that is related to the fifth term in the same way as the second term is related to the first term and fourth term related to third term. 7689 : 120 :: 6178 : 88 :: 3284 : ?", "options": [{"id": "A", "text": "68"}, {"id": "B", "text": "70"}, {"id": "C", "text": "69"}, {"id": "D", "text": "75"}], "answer": "A", "solution": "The pattern in the given series is: Logic: (Sum of all the digits of first term) × 4 = Second term Let's apply the pattern: 7689 : 120 :: 6178 : 88 :: 3284 : ? (Sum of all the digits of first term) × 4 = Second term (7 + 6 + 8 + 9) × 4 = 120 30 × 4 = 120 120 = 120 7689 : 120 :: 6178 : 88 :: 3284 : ? (Sum of all the digits of first term) × 4 = Secon"}, {"q": "Select the option that is related to the fourth term in the same way as the first term is related to the second term and the fifth term is related to the sixth term. 143 ∶ 11 ∶∶ ? ∶ 13 ∶∶ 437 ∶ 19", "options": [{"id": "A", "text": "309"}, {"id": "B", "text": "221"}, {"id": "C", "text": "272"}, {"id": "D", "text": "168"}], "answer": "B", "solution": "The logic followed is: Logic: First-term = Second term × Next prime number According to the above relation, the missing term will be as- Missing term = 13 × next prime number Missing term = 13 × 17 = 221 Hence, Option (2) is correct. Additional Information Some facts about the Prime numbers: A prime number is a natural number greater than 1 that is"}, {"q": "Select the set in which the numbers are related in the same way as are the numbers of the following set. (NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 - Operations on 13 such as adding /subtracting/multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is NOT allowed) (264, 43, 19) (132, 27, 15)", "options": [{"id": "A", "text": "(331, 50, 29)"}, {"id": "B", "text": "(240, 59, 39)"}, {"id": "C", "text": "(176, 39, 23)"}, {"id": "D", "text": "(151, 63, 52)"}], "answer": "C", "solution": "Logic: (Second number - Third number) × 11 = First number (176, 39, 23) → (39 - 23) × 11 = 16 × 11 = 176 Hence, ' (176, 39, 23) ' is the correct answer."}, {"q": "Select the option that is related to the fifth number in the same way as the second number is related to the first number and fourth number is related to third number. 102 : 119 : : 78 : 91 : : 114 : ?", "options": [{"id": "A", "text": "133"}, {"id": "B", "text": "147"}, {"id": "C", "text": "182"}, {"id": "D", "text": "126"}], "answer": "A", "solution": "The pattern followed is : 17 × 6 = 102; 17 × 7 = 119; 13 × 6 = 78; 13 × 7 = 91; Similarly, 19 × 6 = 114; 19 × 7 = 133 Hence, ‘133’ is the correct answer."}, {"q": "From the given alternatives, select the option in which the set of numbers follows the same logic/rule/relationship as the numbers given below. (8, 33, 49)", "options": [{"id": "A", "text": "(17, 69, 103)"}, {"id": "B", "text": "(13, 52, 79)"}, {"id": "C", "text": "(7, 29, 42)"}, {"id": "D", "text": "(9, 38, 57)"}], "answer": "A", "solution": "Given set: (8, 33, 49) The logic followed here is, 1st number × 4 + 1 = 2nd number 1st number × 6 + 1 = 3rd number ⇒ 8 × 4 + 1 = 32 + 1 = 33 ⇒ 8 × 6 + 1 = 48 + 1 = 49 Now, checking the options: Option 1: (17, 69, 103) ⇒ 17 × 4 + 1 = 68 + 1 = 69 ⇒ 17 × 6 + 1 = 102 + 1 = 103 Option 2: (13, 52, 79) ⇒ 13 × 4 + 1 = 52 + 1 = 53 ≠ 2nd number ⇒ 13 × 6 + 1 "}, {"q": "Select the option that is related to the third number in the same way as the second number is related to the first number. 14 : 112 :: 18 : ?", "options": [{"id": "A", "text": "180"}, {"id": "B", "text": "181"}, {"id": "C", "text": "184"}, {"id": "D", "text": "183"}], "answer": "A", "solution": "The logic followed here is:- 1st number × ((1st number ÷ 2) + 1) = Second number. For 14 : 112 14 × ((14 ÷ 2) + 1) = 14 × (7 + 1) = 14 × 8 = 112 Similarly, For 18 : ? 18 × ((18 ÷ 2) + 1) = 18 × (9 + 1) = 18 × 10 = 180 Hence, \"option 1\" is the correct answer."}, {"q": "In the following question, select the related number from the given alternatives. 45 : 400 :: 64 : ?", "options": [{"id": "A", "text": "529"}, {"id": "B", "text": "484"}, {"id": "C", "text": "625"}, {"id": "D", "text": "576"}], "answer": "D", "solution": "The logic followed here is: 45 → 4 × 5 = 20 → 20 2 = 400 Similarly, 64 → 6 × 4 = 24 → 24 2 = 576 Hence, the correct answer is 576 ."}]}, "reading-comprehension": {"subject": "english", "topic": "Reading Comprehension", "title": "CT 28: Reading Comprehension - 02", "provider": "Testbook", "duration": null, "questions": [{"q": "What is the closest synonym for “paradigm” as used in the passage?", "options": [{"id": "A", "text": "Experiment"}, {"id": "B", "text": "Model"}, {"id": "C", "text": "Contradiction"}, {"id": "D", "text": "Problem"}], "answer": "B", "solution": "The correct answer is: Option 2) Model i.e. 'Model'. Key Points The word \"paradigm\" means a typical example or pattern of something; a model. (प्रतिमान) Example: The scientific method serves as a paradigm for rigorous experimentation. \"Model\" means a representative form or pattern. (मॉडल) Example: The architect used a scale model to demonstrate the"}, {"q": "What can be concluded about current thinking on obesity and diabetes?", "options": [{"id": "A", "text": "It is based on two main assumptions: that obesity causes diabetes, and that obesity is caused by an energy imbalance, but these may not be entirely correct."}, {"id": "B", "text": "It has successfully solved the obesity epidemic."}, {"id": "C", "text": "It ignores all previous research."}, {"id": "D", "text": "It only considers genetic factors."}], "answer": "A", "solution": "The correct answer is ' Option 1 '. Key Points A) The passage implies that the current assumptions regarding the causes of obesity and diabetes may be flawed and need to be reconsidered. It mentions that current paradigms focus on obesity causing diabetes and an energy imbalance causing obesity, but these views may not fully account for the situati"}, {"q": "According to the passage, what happened to the theory linking sugar to obesity and diabetes after the Second World War?", "options": [{"id": "A", "text": "It became the dominant paradigm."}, {"id": "B", "text": "It was dismissed and replaced by the focus on dietary fat."}, {"id": "C", "text": "It was proven to be false."}, {"id": "D", "text": "It was widely implemented in public health policies."}], "answer": "B", "solution": "The correct answer is ' Option 2 '. Key Points A) The passage explains that the German and Austrian clinical investigators' theory linking sugar to obesity and diabetes did not take hold after the Second World War. Instead, a different focus took over. \"But the German and Austrian thinking evaporated with the war, and the possibility that sugar was"}, {"q": "What is the tone of the passage?", "options": [{"id": "A", "text": "Cautious and critical"}, {"id": "B", "text": "Humorous and sarcastic"}, {"id": "C", "text": "Indifferent and passive"}, {"id": "D", "text": "Aggressive and confrontational"}], "answer": "A", "solution": "The correct answer is ' Option 1 '. Key Points A) The author carefully examines the history and current understanding of the causes of obesity and diabetes, questioning established paradigms and suggesting that they should be reconsidered. This reflects a cautious and critical tone. \"Whether this is the case with the current epidemics is an all-too"}, {"q": "What is the main idea of the passage?", "options": [{"id": "A", "text": "The causes of obesity and diabetes have always been correctly understood."}, {"id": "B", "text": "Persistent misconceptions and paradigms in nutrition science have led to possibly flawed assumptions about the causes of obesity and diabetes, which may need to be reconsidered."}, {"id": "C", "text": "Sugar has never been considered as a possible cause of chronic diseases."}, {"id": "D", "text": "Pathological science only exists in the field of chemistry."}], "answer": "B", "solution": "The correct answer is ' Option 2 '. Key Points A) The passage explores the idea that misconceptions and entrenched paradigms in the field of nutrition science have potentially led to flawed assumptions about the causes of obesity and diabetes. This is highlighted by the historical shift in thinking and the possibility that the role of sugar has bee"}, {"q": "What is the closest antonym for “paralysed” as used in the passage?", "options": [{"id": "A", "text": "Awake"}, {"id": "B", "text": "Restless"}, {"id": "C", "text": "Mobile"}, {"id": "D", "text": "Exhausted"}], "answer": "C", "solution": "The correct answer is: Option 3) Mobile i.e. 'Mobile'. Key Points The word \"paralysed\" means unable to move or act. (लकवाग्रस्त) Example: After the accident, he was paralyzed from the waist down. \"Mobile\" means able to move or be moved freely or easily. (गतिशील) Example: After the surgery, the patient became mobile again and could walk without assi"}, {"q": "What can be concluded about the cultural reporting of sleep paralysis?", "options": [{"id": "A", "text": "The biological experience is similar across cultures, but its interpretation varies according to local folklore and beliefs."}, {"id": "B", "text": "Only modern cultures report sleep paralysis."}, {"id": "C", "text": "Sleep paralysis is unique to Japanese culture."}, {"id": "D", "text": "Cultures without television do not report sleep paralysis."}], "answer": "A", "solution": "The correct answer is ' Option 1 '. Key Points A) The passage indicates that sleep paralysis is reported across a variety of cultures, but the interpretations of the experience are influenced by local folklore and beliefs. The author mentions that \"cultural beliefs and folklores shape the interpretation of these experiences\" even though the biologi"}, {"q": "According to the passage, what is the biological purpose of paralysis during REM sleep?", "options": [{"id": "A", "text": "To ensure deeper sleep"}, {"id": "B", "text": "To prevent people from acting out their dreams and endangering themselves or others"}, {"id": "C", "text": "To cause hallucinations"}, {"id": "D", "text": "To help people remember their dreams"}], "answer": "B", "solution": "The correct answer is ' Option 2 '. Key Points A) The passage explains that paralysis during REM sleep is to prevent individuals from acting out their dreams, which could potentially endanger themselves or their sleeping partners. \"If we weren’t paralysed, we would act out our dreams, endangering ourselves and our sleeping partners.\" This supports "}, {"q": "What is the tone of the passage?", "options": [{"id": "A", "text": "Informative and personal"}, {"id": "B", "text": "Humorous and mocking"}, {"id": "C", "text": "Indifferent and detached"}, {"id": "D", "text": "Aggressive and confrontational"}], "answer": "A", "solution": "The correct answer is ' Option 1 '. Key Points A) The passage provides detailed information about sleep paralysis, its connection to REM sleep, and its cultural significance. It also includes the author's personal experiences, making the tone both informative and personal. This supports Option 1: \"Informative and personal.\" Therefore, the tone of t"}, {"q": "What is the main idea of the passage?", "options": [{"id": "A", "text": "REM sleep is not important for humans."}, {"id": "B", "text": "Only people with mental health issues experience sleep paralysis."}, {"id": "C", "text": "Sleep paralysis is a common and terrifying phenomenon, rooted in REM sleep, often accompanied by vivid hallucinations and widely reported across cultures."}, {"id": "D", "text": "Dreams have no connection to physical sensations."}], "answer": "C", "solution": "The correct answer is ' Option 3 '. Key Points A) The passage describes the phenomenon of sleep paralysis, its connection to REM sleep, and the terrifying hallucinations that accompany it. The author shares personal experiences of sleep paralysis and explains how it has been reported across different cultures. This supports Option 3: \"Sleep paralys"}]}, "modern-history": {"subject": "general-awareness", "topic": "Modern History", "title": "CT 31: Modern History - Miscellaneous", "provider": "Testbook", "duration": null, "questions": [{"q": "Match the following Social-reforms and their leaders in India. (A) Raja Rammohan Roy (1) Theosophical Society (B) Mahadev Gobind Ranade (2) Tattavabodhini Sabha (C) Debendranath Tagore (3) Atmiya Sabha (D) Annie Besant (4) Prarthana Samaj", "options": [{"id": "A", "text": "(A)-(3), (B)-(4), (C)-(2), (D)-(1)"}, {"id": "B", "text": "(A)-(1), (B)-(4), (C)-(2), (D)-(3)"}, {"id": "C", "text": "(A)-(3), (B)-(2), (C)-(1), (D)-(4)"}, {"id": "D", "text": "(A)-(4), (B)-(2), (C)-(3), (D)-(1)"}], "answer": "A", "solution": "Raja Rammohan Roy is associated with Atmiya Sabha (3), Mahadev Gobind Ranade with Prarthana Samaj (4), Debendranath Tagore with Tattvabodhini Sabha (2), and Annie Besant with Theosophical Society (1). These leaders contributed to key social reforms in India through their respective organizations."}, {"q": "On 8 th April 1929, who among the following two revolutionists threw a bomb in the Central Legislative Assembly?", "options": [{"id": "A", "text": "Bhagat Singh and Rajguru"}, {"id": "B", "text": "Bhagat Singh and Ram Prasad Bismil"}, {"id": "C", "text": "Bhagat Singh and Batukeshwar Dutt"}, {"id": "D", "text": "Bhagat Singh and Sukhdev"}], "answer": "C", "solution": "The question highlights the revolutionary act of Bhagat Singh and Batukeshwar Dutt, who threw a bomb in the Central Legislative Assembly on 8th April 1929 to protest oppressive British laws. Their intent was not to harm but to draw attention. They were arrested after distributing pamphlets and shouting anti-colonial slogans."}, {"q": "Which of the following statements is correct with respect to the Nehru Report of 1928?", "options": [{"id": "A", "text": "It was drafted by the Jawahar Lal Nehru."}, {"id": "B", "text": "The report defined 'Independent Republic' as the form of government desired by India."}, {"id": "C", "text": "The Report recommended Dominion status"}, {"id": "D", "text": "When the Nehru Report was published, Lord Birkenhead was the Viceroy of British India."}], "answer": "C", "solution": "Nehru Report, 1928: It was drafted by the Motilal Nehru. Hence option 1 is incorrect. This report defined Dominion Status as the form of government desired by India. Hence option 2 is incorrect. The Report recommended Universal Adult Suffrage. Hence option 3 is correct. At that time, Lord Irwin was the Viceroy of British India. Hence option 4 is in"}, {"q": "Where was the government of ‘Free India’ inaugurated by Subhash Chandra Bose?", "options": [{"id": "A", "text": "Rangoon"}, {"id": "B", "text": "Calcutta"}, {"id": "C", "text": "Tokyo"}, {"id": "D", "text": "Singapore"}], "answer": "D", "solution": "Option 4 is correct, i.e. Singapore . The government of ‘Free India’ was inaugurated by Subhash Chandra Bose in Singapore . The Provisional Government of Free India was founded in October 1943 by Subhas Chandra Bose . The Provisional Government of Free India also known as the Azad Hind Government. It was influenced by Neta Ji Subhash Chandra Bose ,"}, {"q": "The ________ commercial companies set up their base in India during the Mughal Empire at Masulipatnam in 1605.", "options": [{"id": "A", "text": "British"}, {"id": "B", "text": "French"}, {"id": "C", "text": "Portuguese"}, {"id": "D", "text": "Dutch"}], "answer": "D", "solution": "The Dutch established their bases at various places such as Cochin, Masulipatnam, Negapatam and Pulicat . The French establishments included Karikal, Mahe, Chandernagore, Pondicherry etc. The Portuguese establishments included Cochin, Goa etc. The British established bases in Surat, Bombay, Calcutta and Madras initially."}, {"q": "Who is the writer of the song “Sare Jahan Se Achha Hindustan Hamara”?", "options": [{"id": "A", "text": "Mohammad Iqbal"}, {"id": "B", "text": "Rabindranath Tagore"}, {"id": "C", "text": "Chandra Shekhar Azad"}, {"id": "D", "text": "Bhagat Singh"}], "answer": "A", "solution": "Mohammad Iqbal wrote the song \"Sare Jahan Se Achha Hindustan Hamara.\" This Urdu song, also known as \"Tarana-e-Hind,\" was published on August 16, 1904, in the weekly journal Ittihad."}, {"q": "Which British retired Civil Service Officer took the initiative to convene the first meeting of the Indian National Union?", "options": [{"id": "A", "text": "John Morley"}, {"id": "B", "text": "Edwin Montagu"}, {"id": "C", "text": "Allan Octavian Hume"}, {"id": "D", "text": "Gilbert Elliot"}], "answer": "C", "solution": "Allan Octavian Hume convened the first meeting of the Indian National Union in 1884, which later evolved into the Indian National Congress (INC). The first session of INC was held in 1885 in Bombay, presided over by W.C. Bannerji, with 72 delegates attending."}, {"q": "The Tri-Color which was hoisted in Stuttgart by Madam Cama was smuggled into British India by:", "options": [{"id": "A", "text": "Veer Savarkar"}, {"id": "B", "text": "Kishan Singh"}, {"id": "C", "text": "Indulal Yagnik"}, {"id": "D", "text": "Bhikaji Cama"}], "answer": "C", "solution": "The correct answer is Indulal Yagnik . The Tri-Color which was hoisted in Stuttgart by Madam Cama was smuggled into British India by Indulal Yagnik . Key Points Madam Bhikaji Cama: She was the first lady to first hoist India’s flag on foreign soil. The tri-colour flag was hoisted at the International Socialist Conference at Stuttgart in Germany in "}, {"q": "Read the following statements with reference to the First War of Indian Independence, 1857 and choose the CORRECT option. a) It is also known as the Sepoy Mutiny. b) It was started in Udhampur district of Jammu and Kashmir. c) It was widespread in Delhi, Agra, Kanpur, and Lucknow.", "options": [{"id": "A", "text": "All a, b, c are TRUE"}, {"id": "B", "text": "a and c are TRUE and b is FALSE"}, {"id": "C", "text": "All a, b, c are FALSE"}, {"id": "D", "text": "a and b are TRUE and c is FALSE"}], "answer": "B", "solution": "The correct answer is a and c are TRUE and b is FALSE . Key Points The revolt of 1857 is also known as the first war of Independence . First started on 10 th May 1857 in Meerut by Indian troops of British East India Company . As the revolt started with the mutiny of Indian troops or also were called sepoys the revolt is also known as Sepoy Mutiny ."}, {"q": "Which of the following pairs is not correctly matched?", "options": [{"id": "A", "text": "Hector Munro - Battle of Buxar"}, {"id": "B", "text": "Lord Hastings - Anglo-Nepal War"}, {"id": "C", "text": "Lord wellesely - Fourth Anglo Mysore War"}, {"id": "D", "text": "Lord Cornwallis - Third Anglo-Maratha War"}], "answer": "D", "solution": "The pair \"Lord Cornwallis - Third Anglo-Maratha War\" is incorrectly matched. The Third Anglo-Maratha War (1817-1818) was led by Governor-General Lord Hastings, not Lord Cornwallis. Therefore, this pair is not correctly matched."}]}, "full-mock-demo": {"subject": "full", "topic": "SSC CGL Full Mock", "title": "SSC CGL Mocks 2025 - SSC Super Practice #57", "provider": "Oliveboard", "duration": 10, "questions": [{"q": "In a 5-km race, A beats B by 750 metres and C by 1260 metres. By how many metres does B beat C in the same race? 5 किलोमीटर की दौड़ में, A, B को 750 मीटर से और C को 1260 मीटर से हराता है। उसी दौड़ में B, C को कितने मीटर से हराता है?", "options": [{"id": "A", "text": "700 metres 700 मीटर"}, {"id": "B", "text": "600 metres 600 मीटर"}, {"id": "C", "text": "500 metres 500 मीटर"}, {"id": "D", "text": "400 metres 400 मीटर"}], "answer": "B", "solution": "Let B beat C by T metres. Length of race course = Distance covered by A = 5 km = 5000 m Distance covered by B = 5000 - 750 = 4250 m Distance covered by C = 5000 - 1260 = 3740 m And Distance covered by B = 5000 m Distance covered by C = 5000 - T m Now, 5000/(5000 - T) = 4250/3740 5000 - T = 4400 T = 600 m"}, {"q": "In a 100-m race, A beats B by 20 m and B beats C by 5 m. In the same race, find the distance by which A beats C. 100 मीटर की दौड़ में, A, B को 20 मीटर से हराता है और B, C को 5 मीटर से हराता है। उसी दौड़ में, वह दूरी ज्ञात कीजिए जिससे A, C को हराता है।", "options": [{"id": "A", "text": "22 m 22 मी"}, {"id": "B", "text": "24 m 24 मी"}, {"id": "C", "text": "26 m 26 मी"}, {"id": "D", "text": "25 m 25 मी"}], "answer": "B", "solution": "Ratio of speeds of A and B = 100 : 80 = 5 : 4 Ratio of speeds of B and C = 100 : 95 = 20 : 19 Ratio of speeds of A and C = 5/4 * 20/19 = 25/19 When A runs 100 m, C runs (19/25) * 100 = 76 m A beats C by = 100 - 76 = 24 m"}, {"q": "P and Q take part in 400 m race. P runs at 12 km/hr. P gives Q a start of 20 m and still beats him by 13 seconds. The speed of Q is: (Round up to two decimal places.) P और Q 400 मीटर की दौड़ में भाग लेते हैं। P 12 किमी/घंटा की गति से दौड़ता है। P, Q से 20 मीटर आगे रहता है और फिर भी उसे 13 सेकंड से हरा देता है। Q की गति है: (दो दशमलव स्थानों तक पूर्णांकित करें।)", "options": [{"id": "A", "text": "11.38 km/hr 11.38 किमी/घंटा"}, {"id": "B", "text": "10.29 km/hr 10.29 किमी/घंटा"}, {"id": "C", "text": "11.61 km/hr 11.61 किमी/घंटा"}, {"id": "D", "text": "10.87 km/hr 10.87 किमी/घंटा"}], "answer": "B", "solution": "Time taken by P to complete the race = (400/1000)/(12) = 1/30 hours Time taken by Q to complete the race = 1/30 + 13/3600 = 133/3600 hours Distance covered by Q = 400 - 20 = 380 m = 0.38 km Speed of Q = 0.38/(133/3600) = 10.29 km/hr"}, {"q": "Atul gives Vishu a head-start of 20 seconds in a 900 m race and beats him by 135 m. While running the same race again Atul gives a start of 189 m and beats him by 8 seconds. In how much time can Vishu complete the full race of 900 m? अतुल 900 मीटर की दौड़ में विशु को 20 सेकंड की बढ़त देता है और उसे 135 मीटर से पीछे छोड़ देता है। उसी दौड़ में फिर से भागते समय अतुल 189 मीटर की बढ़त देता है और उसे 8 सेकंड से पीछे छोड़ देता है। विशु 900 मीटर की पूरी दौड़ कितने समय में पूरी कर सकता है?", "options": [{"id": "A", "text": "3 minutes 30 seconds 3 मिनट 30 सेकंड"}, {"id": "B", "text": "2 minutes 50 seconds 2 मिनट 50 सेकंड"}, {"id": "C", "text": "3 minutes 20 seconds 3 मिनट 20 सेकंड"}, {"id": "D", "text": "3 minutes 10 seconds 3 मिनट 10 सेकंड"}], "answer": "C", "solution": "Here Atul's speed as A m/s Vishu's speed as V m/s Let:- Time taken by Atul to cover 900m as Ta seconds Time taken by Vishu to cover 900m as Ty seconds Atu's speed: 900/T a Vishu's speed in the first race; 765/ T a +20 vishu's speed in the second race: 711/T a +8 Equating the two speeds: 765/ T a +20=711/T a +8 Multiply both sides by (Ta + 20)(Ta +8"}, {"q": "Arun and Bhaskar run a race of 3 km. First, Arun gives Bhaskar a head start of 400 m and beats him by 30 seconds. While coming back, Arun gives Bhaskar a lead of 2.5 minutes and gets beaten by 500 m. What is the difference between the times in minutes in which Arun and Bhaskar can run the race for one side separately? अरुण और भास्कर 3 किलोमीटर की दौड़ लगाते हैं। सबसे पहले, अरुण भास्कर को 400 मीटर की बढ़त देता है और उसे 30 सेकंड से हरा देता है। वापस आते समय, अरुण भास्कर को 2.5 मिनट की बढ़त देता है और 500 मीटर से पीछे हो जाता है। अरुण और भास्कर द्वारा एक पक्ष के लिए अलग-अलग दौड़ लगाने में लगने वाले समय (मिनटों में) में क्या अंतर है?", "options": [{"id": "A", "text": "3 min 3 मिनट"}, {"id": "B", "text": "1.5 min 1.5 मिनट"}, {"id": "C", "text": "2.5 min 2.5 मिनट"}, {"id": "D", "text": "2 min 2 मिनट"}], "answer": "B", "solution": "Let: Arun's speed = A m/s Bhaskar's speed = B m/s Race distance = 3000 m First Scenario: Bhaskar runs 2600 m (3000 - 400). Let T be the time (in seconds) for Arun to run 3000 m: A = 3000/T. Bhaskar takes (T + 30) seconds to finish 2600 m: B = 2600/(T + 30). Second Scenario: Bhaskar gets a 2.5-minute (150 s) lead. Bhaskar's time for 3000 m: x = 3000"}, {"q": "In an 800 m race, the ratio of the speeds of two contestants Ankur and Neha is 5:6. If Ankur has a head-start of 200 m, then Ankur will win by 800 मीटर की दौड़ में, दो प्रतियोगियों अंकुर और नेहा की गति का अनुपात 5:6 है। यदि अंकुर 200 मीटर की बढ़त लेता है, तो अंकुर जीत जाएगा।", "options": [{"id": "A", "text": "89 m 89 मी"}, {"id": "B", "text": "80 m 80 मी"}, {"id": "C", "text": "76 m 76 मी"}, {"id": "D", "text": "69 m 69 मी"}], "answer": "B", "solution": "Speeds: Ankur:Neha = 5:6 Ankur runs 600 m (800-200), Neha runs 800 m Time = Distance / Speed t₁ = 600/5 = 120, t₂ = 800/6 = 133.33 Ankur finishes first Neha's distance in 120 = 6 X 120 = 720 m Ankur wins by 800 - 720 = 80 m Option (b) is the correct answer."}, {"q": "Tarun gives Hari a head-start of 60 seconds in a 2400 m race and still beats him by 40 seconds. If the speed of Hari is 6 m/s, find the speed of Tarun. तरुण 2400 मीटर की दौड़ में हरि से 60 सेकंड आगे रहता है और फिर भी उसे 40 सेकंड से हरा देता है। यदि हरि की गति 6 मीटर/सेकंड है, तो तरुण की गति ज्ञात कीजिए।", "options": [{"id": "A", "text": "8.5 m/s 8.5 मीटर/सेकेंड"}, {"id": "B", "text": "7.5 m/s 7.5 मीटर/सेकेंड"}, {"id": "C", "text": "8 m/s 8 मीटर/सेकेंड"}, {"id": "D", "text": "7 m/s 7 मी/से"}], "answer": "C", "solution": "Hari's time = 2400 / 6 = 400 s Tarun's time = 400 - 60 - 40 = 300 s Tarun's speed = 2400 / 300 = 8 m/s Option (c) is the correct answer"}, {"q": "In a 2 km linear race, if P completes the race in 200 seconds and Q in 220 seconds, then the distance by which P beats Q is: 2 किमी की रैखिक दौड़ में, यदि P 200 सेकंड में दौड़ पूरी करता है और Q 220 सेकंड में, तो P द्वारा Q को हरायी गयी दूरी है:", "options": [{"id": "A", "text": "167(6/11) metres 167(6/11) मीटर"}, {"id": "B", "text": "173(7/11) metres 173(7/11) मीटर"}, {"id": "C", "text": "191(7/11) metres 191(7/11) मीटर"}, {"id": "D", "text": "181(9/11) metres 181(9/11) मीटर"}], "answer": "D", "solution": "Distance = 2000 m P's speed = 2000 / 200 = 10 m/s Q's speed = 2000 / 220 = 100/11 m/s In 200 s, Q runs: (100/11) * 200 = 20000/11 m Remaining distance: 2000 - 20000/11 = 2000/11 = 181(9/11) m"}, {"q": "In a race of 1200 m, Ram can beat Shyam by 200 m or by 20 sec. What must be the speed of Ram? 1200 m की एक दौड़ में राम श्याम को 200 m या 20 सेकंड से हरा सकता है, तो राम की चाल कितनी होनी चाहिए?", "options": [{"id": "A", "text": "14 m/sec 14 m/sec"}, {"id": "B", "text": "12 m/sec 12 m/sec"}, {"id": "C", "text": "10 m/sec 10 m/sec"}, {"id": "D", "text": "16 m/sec 16 m/sec"}], "answer": "B", "solution": "Let the speed of Ram and Shyam is 'a' m/sec and 'b' m/sec respectively. Since, Ram beat Shyam by 200 m which means when Ram finishes the race of 1200 m, Shyam can finish only 1000 m. So, Also, Ram beat Shyam by 20 sec which means time taken by Shyam to finish the race is 20 sec more than the time taken by Ram to finish the race. So, From equation ("}, {"q": "In a 1500 m race, Anil beats Bakul by 150 m and in the same race Bakul beats Charles by 75 m. By what distance does Anil beat Charles? 1500 m की एक दौड़ में, अनिल ने बकुल को 150 m से हराया और समान दौड़ में बकुल ने चार्ल्स को 75 m से हराया। अनिल ने चार्ल्स को कितनी दूरी से हराया?", "options": [{"id": "A", "text": "217.50 m 217.50 m"}, {"id": "B", "text": "200.15 m 200.15 m"}, {"id": "C", "text": "293.50 m 293.50 m"}, {"id": "D", "text": "313.75 m 313.75 m"}], "answer": "A", "solution": "Since, Anil beats Bakul by 150 m. Which means when Anil complete 1500 m, Bakul completed only 1350 m. Also, Bakul beats Charles by 75 m. Which means when Bakul complete 1500 m, Charles completed only 1425 m. Total distance covered by Charles when Bakul completes only 1350 m = 1425 * (1350/1500) = 1282.5 m Hence, the distance by which Anil beats Cha"}]}};
